'use strict';

// MODULES //

var numelDimension = require( '@stdlib/ndarray/base/numel-dimension' );
var getStride = require( '@stdlib/ndarray/base/stride' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );


// MAIN //

/**
* Computes the sample variance of a one-dimensional single-precision floating-point ndarray, ignoring `NaN` values.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing an input ndarray
* @param {number} correction - degrees of freedom adjustment
* @returns {number} sample variance
*/
function snanvariance( arrays, correction ) {
	var stride;
	var offset;
	var sumsq;
	var count;
	var data;
	var mean;
	var ix;
	var x;
	var N;
	var i;
	var v;

	x = arrays[ 0 ];

	N = numelDimension( x, 0 );
	data = getData( x );
	stride = getStride( x, 0 );
	offset = getOffset( x );

	mean = 0.0;
	sumsq = 0.0;
	count = 0;

	// First pass: compute mean of non-NaN values:
	ix = offset;
	for ( i = 0; i < N; i++ ) {
		v = data[ ix ];
		if ( !isnan( v ) ) {
			mean += v;
			count += 1;
		}
		ix += stride;
	}

	if ( count - correction <= 0 ) {
		return NaN;
	}

	mean /= count;

	// Second pass: compute squared deviations:
	ix = offset;
	for ( i = 0; i < N; i++ ) {
		v = data[ ix ];
		if ( !isnan( v ) ) {
			v -= mean;
			sumsq += v * v;
		}
		ix += stride;
	}

	return sumsq / ( count - correction );
}


// EXPORTS //

module.exports = snanvariance;
